def ordenar_e_contar(valores):
    a = list(valores); deslocamentos = 0
    for i in range(1,len(a)):
        chave = a[i]; j = i-1
        while j >= 0 and a[j] > chave:
            a[j+1] = a[j]; j -= 1; deslocamentos += 1
        a[j+1] = chave
    return a,deslocamentos
assert ordenar_e_contar([1,2,3]) == ([1,2,3],0)
assert ordenar_e_contar([3,2,1]) == ([1,2,3],3)
